<script setup lang="ts">
import StyledSelect from '../app-host/StyledSelect.vue'
import { randomUUID } from '../services/uuid'
import {computed,ref} from 'vue'
import {useQuery} from '@tanstack/vue-query'
import {api,type Node,type Task} from '../services/api'
import {readTaskQuery} from '../services/task-query-lifecycle'
import {useDesktop} from '../desktop/store'
const props=defineProps<{viewTabId:string}>(),desktop=useDesktop(),view=computed(()=>desktop.state!.views[props.viewTabId]!),nodeId=computed(()=>String(view.value.state.nodeId||view.value.resourceRef?.nodeId||view.value.resourceRef?.id||''))
const desired=computed({get:()=>String(view.value.state.firewallDesired||''),set:value=>{preview.value=undefined;desktop.patchView(props.viewTabId,'firewallDesired',value)}}),preview=ref<{current:string[];add:string[];remove:string[];zone:string;planHash:string;permanentAdd:string[];permanentRemove:string[]}>(),previewError=ref('')
const selectedNode=computed({get:()=>nodeId.value,set:value=>{preview.value=undefined;desktop.patchView(props.viewTabId,'taskAfter','');desktop.patchView(props.viewTabId,'serviceAfter','');desktop.patchView(props.viewTabId,'nodeId',value)}})
const taskAfter=computed(()=>String(view.value.state.taskAfter||''))
const serviceAfter=computed(()=>String(view.value.state.serviceAfter||''))
const firewallTaskNode=computed(()=>String(view.value.state.firewallTaskNode||''))
const firewallTaskId=computed(()=>String(view.value.state.firewallTaskId||''))
interface Capabilities {platform:string;services:string;firewall:string;scheduledTasks:string}
const nodes=useQuery({queryKey:['nodes'],queryFn:()=>api<{items:Node[]}>('/nodes')}),caps=useQuery({queryKey:['system-capabilities',nodeId],queryFn:()=>api<Capabilities>(`/nodes/${encodeURIComponent(nodeId.value)}/system/capabilities`),enabled:computed(()=>!!nodeId.value)})
const available=(value?:string)=>!!value&&value!=='unavailable'&&value!=='unsupported'
// Status readers such as Windows netsh and macOS pf do not implement rule changes.
const servicesAvailable=computed(()=>available(caps.data.value?.services)),firewallAvailable=computed(()=>caps.data.value?.platform==='linux'&&caps.data.value?.firewall==='firewalld'),tasksAvailable=computed(()=>available(caps.data.value?.scheduledTasks))
const services=useQuery({queryKey:['system-services',nodeId,serviceAfter],queryFn:()=>api<{items:{name:string;state:string;description?:string}[];nextAfter?:string}>(`/nodes/${encodeURIComponent(nodeId.value)}/system/services?limit=100&after=${encodeURIComponent(serviceAfter.value)}`),enabled:computed(()=>!!nodeId.value&&servicesAvailable.value)}),firewall=useQuery({queryKey:['system-firewall',nodeId],queryFn:()=>api<{backend:string;state:string;detail?:string}>(`/nodes/${encodeURIComponent(nodeId.value)}/system/firewall`),enabled:computed(()=>!!nodeId.value)}),tasks=useQuery({queryKey:['system-tasks',nodeId,taskAfter],queryFn:()=>api<{items:{name:string;state:string;schedule?:string}[];nextAfter?:string}>(`/nodes/${encodeURIComponent(nodeId.value)}/system/tasks?after=${encodeURIComponent(taskAfter.value)}`),enabled:computed(()=>!!nodeId.value&&tasksAvailable.value)})
const firewallTask=useQuery({queryKey:['tasks','system-firewall',firewallTaskId],queryFn:({signal})=>readTaskQuery(signal,()=>api<{task:Task}>(`/tasks/${encodeURIComponent(firewallTaskId.value)}`,{signal})),enabled:computed(()=>!!firewallTaskId.value),refetchInterval:2000})
const mutationRequests=computed<Record<string,string>>({get:()=>((view.value.state.systemMutationRequests||{}) as Record<string,string>),set:value=>desktop.patchView(props.viewTabId,'systemMutationRequests',value)})
function mutationKey(scope:string){return mutationRequests.value[scope]||(mutationRequests.value={...mutationRequests.value,[scope]:randomUUID()},mutationRequests.value[scope])}
function mutationDone(scope:string){const next={...mutationRequests.value};delete next[scope];mutationRequests.value=next}
const hasActiveFirewallTask=computed(()=>!!firewallTaskId.value&&!['SUCCEEDED','FAILED','CANCELLED','INTERRUPTED'].includes(firewallTask.data.value?.task.state||''))
const canConfirm=computed(()=>firewallTask.data.value?.task.phase==='awaiting_confirmation'&&firewallTask.data.value?.task.state==='RUNNING'&&!!firewallTaskNode.value)
const firewallStatus=computed(()=>{const t=firewallTask.data.value?.task;return !t?'任务状态待查询':t.state==='SUCCEEDED'?'已确认保留':t.phase==='awaiting_confirmation'?'规则已应用，等待确认':t.state==='QUEUED'?'排队中':t.state==='WAITING_NODE'?'等待节点':`${t.state} · ${t.phase} · ${t.error||''}`})
async function serviceAction(name:string,action:string){if(!servicesAvailable.value){window.alert(`节点服务管理不可用：${caps.data.value?.services||'尚未探测'}`);return}if(!confirm(`${action} 服务 ${name}？`))return;const scope=`service:${nodeId.value}:${name}:${action}`;try{await api(`/nodes/${encodeURIComponent(nodeId.value)}/system/services/actions`,{method:'POST',headers:{'Idempotency-Key':mutationKey(scope)},body:JSON.stringify({name,action})});mutationDone(scope);await services.refetch()}catch(e){window.alert(String(e))}}
async function previewFirewall(){if(!firewallAvailable.value){previewError.value=`节点防火墙不可用：${caps.data.value?.firewall||'尚未探测'}`;return}const target=nodeId.value,draft=desired.value;previewError.value='';try{const result=await api<{current:string[];add:string[];remove:string[];zone:string;planHash:string;permanentAdd:string[];permanentRemove:string[]}>(`/nodes/${encodeURIComponent(target)}/system/firewall/preview`,{method:'POST',body:JSON.stringify({desired:draft.split('\n').map(x=>x.trim()).filter(Boolean)})});if(nodeId.value===target&&desired.value===draft)preview.value=result}catch(e){previewError.value=String(e)}}
async function taskAction(name:string,action:string){if(!tasksAvailable.value){window.alert(`计划任务管理不可用：${caps.data.value?.scheduledTasks||'尚未探测'}`);return}if(!confirm(`${action} 计划任务 ${name}？`))return;const scope=`task:${nodeId.value}:${name}:${action}`;try{await api(`/nodes/${encodeURIComponent(nodeId.value)}/system/tasks/actions`,{method:'POST',headers:{'Idempotency-Key':mutationKey(scope)},body:JSON.stringify({name,action})});mutationDone(scope);await tasks.refetch()}catch(e){window.alert(String(e))}}
async function applyFirewall(){const plan=preview.value;if(!plan||!firewallAvailable.value)return;const target=nodeId.value,rules=desired.value.split('\n').map(x=>x.trim()).filter(Boolean);if(!confirm(`应用节点 ${target} 区域 ${plan.zone} 的运行和永久端口规则？变更将在节点任务中执行，并等待二次确认。`))return;const scope=`firewall-apply:${target}:${plan.planHash}`;try{const confirmUntil=new Date(Date.now()+60000).toISOString();const {task}=await api<{task:Task}>(`/nodes/${encodeURIComponent(target)}/system/firewall/apply`,{method:'POST',headers:{'Idempotency-Key':mutationKey(scope)},body:JSON.stringify({desired:rules,confirmUntil,planHash:plan.planHash})});mutationDone(scope);desktop.patchView(props.viewTabId,'firewallTaskNode',target);desktop.patchView(props.viewTabId,'firewallTaskId',task.taskId);await firewallTask.refetch()}catch(e){previewError.value=String(e)}}
async function confirmFirewall(){const taskId=firewallTaskId.value,target=firewallTaskNode.value;if(!canConfirm.value)return;const scope=`firewall-confirm:${target}:${taskId}`;try{await api(`/nodes/${encodeURIComponent(target)}/system/firewall/confirm`,{method:'POST',headers:{'Idempotency-Key':mutationKey(scope)},body:JSON.stringify({taskId})});mutationDone(scope);await firewallTask.refetch()}catch(e){previewError.value=String(e)}}
</script>
<template><div class="application"><header class="app-heading"><div><span class="eyebrow">SYSTEM</span><h2>系统管理</h2><p>能力探测和服务查询；服务变更需逐项确认并进入任务中心。</p></div><StyledSelect v-model="selectedNode" aria-label="系统节点"><option value="">选择节点</option><option v-for="n in nodes.data.value?.items" :key="n.nodeId" :value="n.nodeId">{{n.name}}</option></StyledSelect></header><p v-if="caps.error.value||services.error.value||firewall.error.value||tasks.error.value||previewError" class="error">{{caps.error.value?.message||services.error.value?.message||firewall.error.value?.message||tasks.error.value?.message||previewError}}</p><section v-if="caps.data.value" class="monitor-summary"><h3>后端能力</h3><div class="details-grid"><dt>平台</dt><dd>{{caps.data.value.platform}}</dd><dt>服务</dt><dd>{{caps.data.value.services}}</dd><dt>防火墙</dt><dd>{{caps.data.value.firewall}}</dd><dt>计划任务</dt><dd>{{caps.data.value.scheduledTasks}}</dd><dt>防火墙状态</dt><dd>{{firewall.data.value?.backend||'—'}} · {{firewall.data.value?.state||'—'}}</dd></div><p v-if="firewall.data.value?.detail" class="muted selectable">{{firewall.data.value.detail}}</p></section><section><h3>防火墙差异预览与应用</h3><p class="muted">每行一条目标规则；应用仅支持 Linux firewalld 端口规则。应用后若在期限内未确认，节点会自动回滚。</p><textarea v-model="desired" rows="4" placeholder="目标规则（每行一条）" aria-label="目标防火墙规则"></textarea><div class="action-row"><button :disabled="!firewallAvailable" @click="previewFirewall">计算差异</button><button :disabled="!firewallAvailable||hasActiveFirewallTask||!preview" @click="applyFirewall">确认并应用</button><button v-if="firewallTaskId" :disabled="!canConfirm" class="primary" @click="confirmFirewall">确认保留</button></div><p v-if="firewallTaskId" class="warning">节点 {{firewallTaskNode}} · 变更任务 {{firewallTaskId}} · {{firewallStatus}}。超时将尝试恢复旧规则；最终结果以任务回报为准。</p><div v-if="preview" class="details-grid"><dt>区域</dt><dd>{{preview.zone}}</dd><dt>运行新增</dt><dd>{{preview.add.join('、')||'无'}}</dd><dt>运行移除</dt><dd>{{preview.remove.join('、')||'无'}}</dd><dt>永久新增</dt><dd>{{preview.permanentAdd.join('、')||'无'}}</dd><dt>永久移除</dt><dd>{{preview.permanentRemove.join('、')||'无'}}</dd></div></section><section v-if="services.data.value"><h3>服务列表</h3><div class="action-row"><button :disabled="!serviceAfter" @click="desktop.patchView(props.viewTabId,'serviceAfter','')">服务首批</button><span>名称 {{serviceAfter||'起点'}} 之后</span><button :disabled="!services.data.value.nextAfter||services.isFetching.value" @click="desktop.patchView(props.viewTabId,'serviceAfter',services.data.value!.nextAfter!)">下一批服务</button></div><article v-for="s in services.data.value.items" :key="s.name" class="task-row"><span>{{s.name}} · {{s.state}}</span><small>{{s.description||''}}</small><span class="action-row"><button :disabled="!servicesAvailable" @click="serviceAction(s.name,'start')">启动</button><button :disabled="!servicesAvailable" @click="serviceAction(s.name,'restart')">重启</button><button :disabled="!servicesAvailable" @click="serviceAction(s.name,'stop')">停止</button></span></article><p v-if="!services.data.value.items.length" class="muted">节点未返回服务，或服务后端不可用。</p></section><section v-if="tasks.data.value"><h3>计划任务</h3><div class="action-row"><button :disabled="!taskAfter" @click="desktop.patchView(props.viewTabId,'taskAfter','')">计划任务首批</button><span>名称 {{taskAfter||'起点'}} 之后</span><button :disabled="!tasks.data.value.nextAfter||tasks.isFetching.value" @click="desktop.patchView(props.viewTabId,'taskAfter',tasks.data.value!.nextAfter!)">下一批计划任务</button></div><article v-for="task in tasks.data.value.items" :key="task.name" class="task-row"><span>{{task.name}}</span><small>{{task.schedule||task.state}}</small><span class="action-row"><button :disabled="!tasksAvailable" @click="taskAction(task.name,'enable')">启用</button><button :disabled="!tasksAvailable" @click="taskAction(task.name,'disable')">停用</button></span></article><p v-if="!tasks.data.value.items.length" class="muted">节点未返回计划任务，或服务后端不可用。</p></section></div></template>
